351	  importJSON(data, options = {}) {
352	    const { mode, dryRun } = validateOptions(options);
353	    const incoming = normalizeSnapshot(data);
354	
355	    let next;
356	    if (mode === 'replace') {
357	      next = new Map(incoming.map((document) => [document.id, Object.freeze(structuredClone(document))]));
358	    } else {
359	      // Derive conflicts against the projected state after applying every
360	      // incoming document: a moved-away title frees up for a newcomer, while
361	      // a moved-into title can newly collide.
362	      next = new Map(this.#documents);
363	      const incomingIds = new Set();
364	      const effective = new Map(this.#documents);
365	      const conflicts = new Set();
366	      for (const document of incoming) {
367	        incomingIds.add(document.id);
368	        const current = this.#documents.get(document.id);
369	        if (current && !sameDocument(current, document)) conflicts.add(document.id);
370	        effective.set(document.id, Object.freeze(structuredClone(document)));
371	      }
372	      const titleOwners = new Map();
373	      for (const document of effective.values()) {
374	        const owner = titleOwners.get(document.title);
375	        if (owner === undefined) {
376	          titleOwners.set(document.title, document.id);
377	        } else if (incomingIds.has(document.id) || incomingIds.has(owner)) {
378	          if (incomingIds.has(document.id)) conflicts.add(document.id);
379	          if (incomingIds.has(owner)) conflicts.add(owner);
380	        }
381	      }
382	      if (conflicts.size > 0) {
383	        throw new SnapshotError(
384	          'IMPORT_CONFLICT',
385	          'merge conflicts detected for incoming document ids',
386	          { ids: [...conflicts].sort(compareCodePoints) },
387	        );
388	      }
389	      for (const document of incoming) {
390	        next.set(document.id, Object.freeze(structuredClone(document)));
391	      }
392	    }
393	
394	    const snapshot = buildSnapshot(next.values());
395	    if (!dryRun) this.#documents = next;
396	    return snapshot;
397	  }
398	}
