350	    const result = mutate(candidate, nextLedger);
351	    if (result === false) {
352	      return { snapshot: current.exportJSON(), result: null };
353	    }
354	    const snapshot = candidate.exportJSON();
355	    if (!dryRun) {
356	      save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
357	      current = candidate;
358	      ledger = nextLedger;
359	    }
360	    return { snapshot, result };
361	  }
362	
363	  // Applies every operation in one atomic commit. Existence and
364	  // restore-version checks all run against the pre-commit state, so a batch is
365	  // rejected whole if any operation would fail. Title conflicts are checked
366	  // against the final projected set, making swaps and release-then-reuse
367	  // independent of operation order. Each actually-changed document appends one
368	  // record; a normalized-identical replace or restore appends nothing. Returns
369	  // `{ snapshot, changed }` without persisting when `dryRun` is true or the
370	  // batch is content-preserving.
371	  function commitBatch(operations, dryRun) {
372	    // Pre-commit state checks.
373	    for (const op of operations) {
374	      if (op.type === 'create') {
375	        if (current.get(op.document.id)) {
376	          throw new HttpError(409, 'CONFLICT', `document already exists: ${op.document.id}`);
377	        }
378	      } else if (op.type === 'replace') {
379	        if (!current.get(op.document.id)) {
380	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.document.id}`);
381	        }
382	      } else if (op.type === 'delete') {
383	        if (!current.get(op.id)) {
384	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.id}`);
385	        }
386	      } else if (op.type === 'restore') {
387	        if (!ledger) {
388	          throw new HttpError(404, 'NOT_FOUND', 'history is not enabled');
389	        }
390	        const chain = ledger.entries(op.id);
391	        if (!chain) {
392	          throw new HttpError(404, 'NOT_FOUND', `document never existed: ${op.id}`);
393	        }
394	        const target = ledger.entry(op.id, op.revision);
395	        if (!target) {
396	          throw new HttpError(404, 'NOT_FOUND', `unknown revision ${op.revision} for document ${op.id}`);
397	        }
398	        if (target.action === 'delete') {
399	          throw new HttpError(400, 'INVALID_REVISION', `revision ${op.revision} of document ${op.id} is a delete and cannot be restored`);
400	        }
401	      }
402	    }
403	
404	    const { snapshot, result } = commit((candidate, nextLedger) => {
405	      let changed = false;
406	      for (const op of operations) {
407	        if (op.type === 'create') {
408	          candidate.add(op.document);
409	          if (nextLedger) nextLedger.record(op.document.id, 'create', candidate.get(op.document.id));
410	          changed = true;
411	        } else if (op.type === 'replace') {
412	          const before = current.get(op.document.id);
413	          candidate.remove(op.document.id);
414	          candidate.add(op.document);
415	          const stored = candidate.get(op.document.id);
416	          if (!sameDocument(before, stored)) {
417	            if (nextLedger) nextLedger.record(op.document.id, 'replace', stored);
418	            changed = true;
419	          }
420	        } else if (op.type === 'delete') {
421	          candidate.remove(op.id);
422	          if (nextLedger) nextLedger.record(op.id, 'delete', null);
423	          changed = true;
424	        } else if (op.type === 'restore') {
425	          const before = current.get(op.id);
426	          const target = ledger.entry(op.id, op.revision);
427	          candidate.remove(op.id);
428	          candidate.add(target.document);
429	          const stored = candidate.get(op.id);
430	          if (!before || !sameDocument(before, stored)) {
431	            nextLedger.record(op.id, 'restore', stored);
432	            changed = true;
433	          }
434	        }
435	      }
436	
437	      // Title conflicts are checked against the final projected set, so
438	      // operation order cannot make a swap or release-then-reuse fail.
439	      const titles = new Set();
440	      for (const document of candidate.list()) {
441	        if (titles.has(document.title)) {
442	          throw new HttpError(409, 'CONFLICT', `title conflict in batch: ${document.title}`);
443	        }
444	        titles.add(document.title);
445	      }
446	
447	      return changed;
448	    }, { dryRun });
449	    return { snapshot, changed: result === true };
450	  }
