452	  async function createDocument(req, res) {
453	    const bytes = await readBody(req);
454	    requireIfMatch(req);
455	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
456	    const { snapshot } = commit((candidate, nextLedger) => {
457	      if (candidate.get(document.id)) {
458	        throw new HttpError(409, 'CONFLICT', `document already exists: ${document.id}`);
459	      }
460	      assertTitleFree(candidate, document.title);
461	      candidate.add(document);
462	      if (nextLedger) nextLedger.record(document.id, 'create', candidate.get(document.id));
463	      return true;
464	    });
465	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
466	  }
467	
468	  async function replaceDocument(req, res, id) {
469	    const bytes = await readBody(req);
470	    requireIfMatch(req);
471	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
472	    if (document.id !== id) {
473	      throw new HttpError(400, 'ID_MISMATCH', `path id ${id} does not match body id ${document.id}`);
474	    }
475	    if (!current.get(id)) {
476	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
477	    }
478	    const before = current.get(id);
479	    const { snapshot } = commit((candidate, nextLedger) => {
480	      candidate.remove(id);
481	      assertTitleFree(candidate, document.title);
482	      candidate.add(document);
483	      const stored = candidate.get(id);
484	      // A replace whose normalized content is identical succeeds without
485	      // consuming a revision or touching the files.
486	      if (sameDocument(before, stored)) return false;
487	      if (nextLedger) nextLedger.record(id, 'replace', stored);
488	      return true;
489	    });
490	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
491	  }
492	
493	  function deleteDocument(req, res, id) {
494	    requireIfMatch(req);
495	    if (!current.get(id)) {
496	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
497	    }
498	    const { snapshot } = commit((candidate, nextLedger) => {
499	      candidate.remove(id);
500	      if (nextLedger) nextLedger.record(id, 'delete', null);
501	      return true;
502	    });
503	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
504	  }
505	
506	  function historyDocument(req, res, id) {
507	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for GET /documents/${id}/history`);
508	    const entries = ledger.entries(id);
509	    if (!entries) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
510	    sendJson(res, 200, entries, currentEtag());
511	  }
512	
513	  async function restoreDocument(req, res, id) {
514	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for POST /documents/${id}/restore`);
515	    const bytes = await readBody(req);
516	    requireIfMatch(req);
517	    // Bad UTF-8 is an INVALID_JSON transport-level failure; only once the
518	    // bytes decode do the restore-specific parse/shape rules apply, which
519	    // keep reporting INVALID_REVISION as before.
520	    const text = decodeJsonBody(bytes);
521	    let data;
522	    try {
523	      data = JSON.parse(text);
524	    } catch {
525	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
526	    }
