528	      || Object.keys(data).length !== 1 || !Object.hasOwn(data, 'revision')
529	      || !Number.isInteger(data.revision) || data.revision < 1) {
530	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
531	    }
532	    const chain = ledger.entries(id);
533	    if (!chain) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
534	    const target = ledger.entry(id, data.revision);
535	    if (!target) throw new HttpError(404, 'NOT_FOUND', `unknown revision ${data.revision} for document ${id}`);
536	    if (target.action === 'delete') {
537	      throw new HttpError(400, 'INVALID_REVISION', `revision ${data.revision} of document ${id} is a delete and cannot be restored`);
538	    }
539	    const before = current.get(id);
540	    const { snapshot } = commit((candidate, nextLedger) => {
541	      candidate.remove(id);
542	      assertTitleFree(candidate, target.document.title);
543	      candidate.add(target.document);
544	      const stored = candidate.get(id);
545	      // Restoring the already-current content succeeds without a new record.
546	      if (before && sameDocument(before, stored)) return false;
547	      nextLedger.record(id, 'restore', stored);
548	      return true;
549	    });
550	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
551	  }
552	
553	  async function batch(req, res) {
554	    const bytes = await readBody(req);
555	    requireIfMatch(req);
556	    const data = parseJson(decodeJsonBody(bytes));
557	    const { operations, dryRun } = validateBatchRequest(data);
558	    const { snapshot } = commitBatch(operations, dryRun);
559	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
560	  }
561	
562	  function listTags(req, res) {
563	    sendJson(res, 200, tagStats(current), currentEtag());
564	  }
565	
566	  // Applies the tag rules to the pre-rewrite tag set of every document. Each
567	  // original tag is looked up once, so a rule result is never itself rewritten
568	  // (a→b then b→c moves the original `a` straight to `b`) and swaps resolve
569	  // because `to` names are carried independently of the source keys. Returns
570	  // `{ snapshot, changedIds }` without persisting when `dryRun` is true or the
571	  // rewrite leaves the tag set unchanged.
572	  function commitTagRewrite(rules, dryRun) {
573	    const mapping = new Map(rules.map((rule) => [rule.from, rule.to]));
574	
575	    // Every source must be used by at least one currently-live document.
576	    const used = new Set();
577	    for (const document of current.list()) {
578	      for (const tag of document.tags) used.add(tag);
579	    }
580	    for (const from of mapping.keys()) {
581	      if (!used.has(from)) throw new HttpError(404, 'TAG_NOT_FOUND', `tag not in use: ${from}`);
582	    }
583	
584	    const { snapshot, result } = commit((candidate, nextLedger) => {
585	      const changedIds = [];
586	      for (const document of current.list()) {
587	        if (!document.tags.some((tag) => mapping.has(tag))) continue;
588	        // A null target removes the tag; mapped results are emitted as-is
589	        // without a second lookup, so new names are never chained further.
590	        const nextTags = normalizeTags(
591	          document.tags.flatMap((tag) => {
592	            if (!mapping.has(tag)) return [tag];
593	            const target = mapping.get(tag);
594	            return target === null ? [] : [target];
595	          }),
596	        );
597	        if (sameTags(document.tags, nextTags)) continue;
598	        const updated = { id: document.id, title: document.title, body: document.body, tags: nextTags };
599	        candidate.remove(document.id);
600	        candidate.add(updated);
601	        if (nextLedger) nextLedger.record(document.id, 'replace', candidate.get(document.id));
602	        changedIds.push(document.id);
603	      }
604	      // Tag set unchanged: report the current snapshot and no file/version work.
605	      if (changedIds.length === 0) return false;
606	      changedIds.sort(compareCodePoints);
607	      return changedIds;
608	    }, { dryRun });
609	    return { snapshot, changedIds: result ?? [] };
610	  }
611	
612	  async function rewriteTags(req, res) {
613	    const bytes = await readBody(req);
614	    requireIfMatch(req);
615	    const { rules, dryRun } = validateTagRules(parseJson(decodeJsonBody(bytes)));
616	    const { snapshot, changedIds } = commitTagRewrite(rules, dryRun);
617	    sendJson(res, 200, { snapshot, changedIds }, `"${snapshot.checksum}"`);
618	  }
619	
620	  // Merges an offline-edited incoming snapshot back against its base, keeping
621	  // non-conflicting online edits. The merge is computed against the current
622	  // live state; field/add/delete/title conflicts reject the whole request.
623	  // Each actually-changed document appends one ledger record (create for new
624	  // or reappearing ids, replace for edits, delete for removals), continuing
625	  // that id's revision sequence. Returns `{ snapshot, changedIds }` without
626	  // persisting when `dryRun` is true or the merge leaves the content equal to
627	  // the current state.
628	  function commitReconcile(base, incoming, dryRun) {
629	    const currentSnapshot = current.exportJSON();
630	    const result = reconcileSnapshots(currentSnapshot, base, incoming);
631	    if (result.conflicts.length > 0) {
632	      throw new HttpError(409, 'RECONCILE_CONFLICT', 'reconcile conflicts detected', {
633	        conflicts: result.conflicts,
634	      });
635	    }
636	
637	    const { snapshot } = commit((candidate, nextLedger) => {
638	      if (result.snapshot.checksum === currentSnapshot.checksum) return false;
639	      for (const document of current.list()) candidate.remove(document.id);
640	      for (const document of result.snapshot.documents) candidate.add(document);
641	      if (nextLedger) {
642	        for (const id of result.changedIds) {
643	          const stored = candidate.get(id);
644	          if (stored) {
645	            // A previously-deleted id that reappears continues its chain with a
646	            // create; a changed live document gets a replace.
647	            const action = current.get(id) ? 'replace' : 'create';
648	            nextLedger.record(id, action, stored);
649	          } else {
650	            nextLedger.record(id, 'delete', null);
651	          }
652	        }
653	      }
654	      return true;
655	    }, { dryRun });
656	    return { snapshot, changedIds: result.changedIds };
657	  }
658	
659	  async function reconcile(req, res) {
660	    const bytes = await readBody(req);
661	    requireIfMatch(req);
662	    const { base, incoming, dryRun } = validateReconcileRequest(parseJson(decodeJsonBody(bytes)));
663	    try {
664	      const snapshot = commitReconcile(base, incoming, dryRun).snapshot;
665	      sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
666	    } catch (error) {
667	      // Both snapshots must pass the existing validation; surface those
668	      // failures as INVALID_SNAPSHOT rather than an internal error. Save
669	      // failures keep their 500/IO_ERROR semantics.
670	      if (error instanceof SnapshotError && error.code === 'INVALID_SNAPSHOT') {
671	        throw new HttpError(400, 'INVALID_SNAPSHOT', error.message);
672	      }
673	      throw error;
674	    }
675	  }
676	
677	  async function handle(req, res) {
678	    const url = new URL(req.url, 'http://127.0.0.1');
679	    const segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
680	    const [resource, id, relation] = segments;
681	
682	    if (resource === 'documents' && segments.length === 1) {
683	      if (req.method === 'GET') {
684	        sendJson(res, 200, current.list(), currentEtag());
685	        return;
686	      }
687	      if (req.method === 'POST') {
688	        await createDocument(req, res);
689	        return;
690	      }
691	    } else if (resource === 'documents' && segments.length === 2) {
692	      if (req.method === 'GET') {
693	        const document = current.get(id);
694	        if (!document) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
695	        sendJson(res, 200, document, currentEtag());
696	        return;
697	      }
698	      if (req.method === 'PUT') {
699	        await replaceDocument(req, res, id);
700	        return;
701	      }
702	      if (req.method === 'DELETE') {
703	        deleteDocument(req, res, id);
704	        return;
705	      }
706	    } else if (resource === 'documents' && segments.length === 3 && relation === 'links' && req.method === 'GET') {
707	      const links = current.links(id);
708	      if (!links) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
709	      sendJson(res, 200, links, currentEtag());
710	      return;
711	    } else if (resource === 'documents' && segments.length === 3 && relation === 'history' && req.method === 'GET') {
712	      historyDocument(req, res, id);
713	      return;
714	    } else if (resource === 'documents' && segments.length === 3 && relation === 'restore' && req.method === 'POST') {
715	      await restoreDocument(req, res, id);
716	      return;
717	    } else if (resource === 'batch' && segments.length === 1 && req.method === 'POST') {
718	      await batch(req, res);
719	      return;
720	    } else if (resource === 'tags' && segments.length === 1 && req.method === 'GET') {
721	      listTags(req, res);
722	      return;
723	    } else if (resource === 'tags' && segments.length === 2 && id === 'rewrite' && req.method === 'POST') {
724	      await rewriteTags(req, res);
725	      return;
726	    } else if (resource === 'snapshots' && segments.length === 2 && id === 'reconcile' && req.method === 'POST') {
727	      await reconcile(req, res);
728	      return;
729	    } else if (resource === 'search' && segments.length === 1 && req.method === 'GET') {
730	      sendJson(res, 200, current.search(url.searchParams.get('q') ?? ''), currentEtag());
731	      return;
732	    }
733	    throw new HttpError(404, 'NOT_FOUND', `no route for ${req.method} ${url.pathname}`);
734	  }
735	
736	  const server = http.createServer((req, res) => {
737	    handle(req, res).catch((error) => {
738	      if (res.headersSent) {
