import { Workspace } from './src/workspace.js';
import assert from 'node:assert/strict';

const ws = new Workspace();
ws.add({ id: 'plan', title: '项目计划', body: 'see [[other]]', tags: ['Work', 'work'] });

// 1. duplicate title rejected: exact and whitespace-padded, plain Error
for (const title of ['项目计划', ' 项目计划 ']) {
  assert.throws(() => ws.add({ id: 'other', title, body: 'b', tags: ['X'] }), (e) => {
    assert.equal(e.constructor, Error);
    assert.equal(e.message, 'title already in use: 项目计划');
    return true;
  });
}
// state untouched after rejection
assert.equal(ws.get('other'), null);
assert.deepEqual(ws.get('plan').tags, ['work']);
assert.equal(ws.list().length, 1);
assert.deepEqual(ws.search('项目').map(d => d.id), ['plan']);
assert.deepEqual(ws.links('plan'), { outgoing: ['other'], incoming: [] });
const snapBefore = ws.exportJSON();

// 2. case-sensitive titles coexist
ws.add({ id: 'p2', title: 'Plan', body: 'b' });
ws.add({ id: 'p3', title: 'plan', body: 'b' });

// 3. delete frees the title for a different id
ws.remove('plan');
ws.add({ id: 'other', title: '项目计划', body: 'b' });
assert.equal(ws.get('other').title, '项目计划');

// 4. duplicate id error still works
assert.throws(() => ws.add({ id: 'other', title: 'Fresh', body: 'b' }), /document already exists: other/);

// 5. export -> import round trip always valid
const ws2 = new Workspace();
ws2.importJSON(ws.exportJSON(), { mode: 'replace' });
assert.deepEqual(ws2.exportJSON(), ws.exportJSON());
assert.deepEqual(ws.exportJSON().documents.find(d => d.id === 'other').title, '项目计划');
console.log('workspace API checks OK');
"

