import { Workspace } from './src/workspace.js';
import { createDocumentServer } from './src/server.js';
import assert from 'node:assert/strict';

const ws = new Workspace();
ws.add({ id: 'a', title: 'Alpha', body: 'body a', tags: ['x'] });
ws.add({ id: 'b', title: 'Beta', body: 'body b', tags: ['y'] });
const saved = [];
const server = createDocumentServer({ workspace: ws, save: (snap) => saved.push(snap) });
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const base = 'http://127.0.0.1:' + server.address().port;

const get = async (p) => (await fetch(base + p));
const etag = async () => (await get('/documents')).headers.get('etag');
const batch = async (operations, dryRun) => fetch(base + '/batch', {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'if-match': await etag() },
  body: JSON.stringify(dryRun === undefined ? { operations } : { operations, dryRun }),
});

// swap preview (dryRun): 200, state unchanged
let res = await batch([
  { type: 'replace', document: { id: 'a', title: 'Beta', body: 'body a', tags: ['x'] } },
  { type: 'replace', document: { id: 'b', title: 'Alpha', body: 'body b', tags: ['y'] } },
], true);
assert.equal(res.status, 200);
assert.deepEqual((await get('/documents')).status, 200);
let docs = await (await get('/documents')).json();
assert.deepEqual(docs.map(d => d.title), ['Alpha', 'Beta']);

// commit swap, reversed operation order -> same projected result
res = await batch([
  { type: 'replace', document: { id: 'b', title: 'Alpha', body: 'body b', tags: ['y'] } },
  { type: 'replace', document: { id: 'a', title: 'Beta', body: 'body a', tags: ['x'] } },
]);
assert.equal(res.status, 200);
docs = await (await get('/documents')).json();
assert.deepEqual(docs.map(d => d.title), ['Beta', 'Alpha']);

// create with old title ordered BEFORE the delete of its holder
res = await batch([
  { type: 'create', document: { id: 'c', title: 'Beta', body: 'body c', tags: [] } },
  { type: 'delete', id: 'a' },
]);
assert.equal(res.status, 200);
docs = await (await get('/documents')).json();
assert.deepEqual(docs.map(d => d.id), ['b', 'c']);
assert.equal(docs.find(d => d.id === 'c').title, 'Beta');

// genuine duplicate final titles -> 409 CONFLICT, nothing applied
res = await batch([
  { type: 'replace', document: { id: 'b', title: 'Same', body: 'body b', tags: ['y'] } },
  { type: 'replace', document: { id: 'c', title: 'Same', body: 'body c', tags: [] } },
]);
assert.equal(res.status, 409);
const payload = await res.json();
assert.equal(payload.code, 'CONFLICT');
assert.match(payload.message, /title conflict in batch: Same/);
docs = await (await get('/documents')).json();
assert.deepEqual(docs.map(d => d.title), ['Alpha', 'Beta']);

// single-document POST with duplicate title -> 409 with the shared message
res = await fetch(base + '/documents', {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'if-match': await etag() },
  body: JSON.stringify({ id: 'd', title: ' Beta ', body: 'x', tags: [] }),
});
assert.equal(res.status, 409);
assert.equal((await res.json()).message, 'title already in use: Beta');

server.close();
console.log('HTTP batch/single checks OK');
"
